-- ============================================================================
-- تعبئة أولية لدليل المدارس ومحطات المترو (إلى أن تُرفع الملفات الرسمية الكاملة من لوحة التحكم)
-- المدارس: 150 مدرسة خاصة بتقييم هيئة المعرفة KHDA (متميز، جيد جدًا، جيد) والمنهج والمنطقة.
-- المترو: 55 محطة على الخطين الأحمر والأخضر وفرع إكسبو، مع المنطقة القريبة.
-- يُنفَّذ بعد city_guides.sql. آمن لو أُعيد تشغيله، ورفع الملف الرسمي لاحقًا يحدّث البيانات.
-- ============================================================================
alter table public.transit_stations add column if not exists area_en text;
alter table public.transit_stations alter column lat drop not null;
alter table public.transit_stations alter column lng drop not null;

on conflict (id) do update set rating_en = excluded.rating_en, rating_ar = excluded.rating_ar, inspection_year = excluded.inspection_year,
  curriculum_en = excluded.curriculum_en, curriculum_ar = excluded.curriculum_ar, area_en = coalesce(excluded.area_en, public.schools.area_en), updated_at = now();

on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, line = excluded.line, area_en = excluded.area_en, updated_at = now();

select (select count(*) from public.schools) as schools, (select count(*) from public.transit_stations) as stations;
